package kronex.fun.display.screens.clickgui.components.implement.window.implement.settings.color;
import lombok.RequiredArgsConstructor; import net.minecraft.client.gui.DrawContext; import kronex.fun.features.module.setting.implement.ColorSetting; import kronex.fun.other.utils.display.shape.ShapeProperties; import kronex.fun.other.utils.math.MathUtil; import kronex.fun.display.screens.clickgui.components.AbstractComponent;
@RequiredArgsConstructor public class ColorPresetButton extends AbstractComponent { private final ColorSetting setting; private final int color; public void render(DrawContext context,int mouseX,int mouseY,float delta){rectangle.render(ShapeProperties.create(context.getMatrices(),x,y,8,8).round(2).color(color).build());} public boolean mouseClicked(double mouseX,double mouseY,int button){if(MathUtil.isHovered(mouseX,mouseY,x,y,8,8)&&button==0)setting.setColor(color);return super.mouseClicked(mouseX,mouseY,button);} }